import os
from pathlib import Path

import pytest


def read_note(name: str) -> str:
    """Return the text of the file `name` inside the directory `notes`.

    `notes` is relative to the current working directory. `name` is untrusted
    and may be any string. Files in subdirectories of `notes` may be read, but
    the resolved path (after following `..` components and symlinks) must stay
    inside `notes`. Absolute paths, traversal out of `notes`, and symlinks that
    point outside `notes` all yield "".

    The file is decoded as UTF-8. A missing, unreadable or undecodable file, a
    directory, an empty name, or an invalid name (e.g. containing a NUL byte)
    yields "". This function never raises for any input.
    """
    try:
        if not name or "\x00" in name:
            return ""
        if Path(name).anchor or os.path.isabs(name):
            return ""
        base = Path("notes").resolve()
        target = (base / name).resolve()
        if target == base or not target.is_relative_to(base):
            return ""
        if not target.is_file():
            return ""
        return target.read_text(encoding="utf-8")
    except (OSError, ValueError, RuntimeError):
        return ""


@pytest.fixture
def workdir(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    (tmp_path / "notes").mkdir()
    (tmp_path / "notes" / "a.txt").write_text("hello", encoding="utf-8")
    (tmp_path / "secret.txt").write_text("TOP SECRET", encoding="utf-8")
    monkeypatch.chdir(tmp_path)
    return tmp_path


def test_reads_existing_file(workdir: Path) -> None:
    assert read_note("a.txt") == "hello"


def test_reads_unicode(workdir: Path) -> None:
    (workdir / "notes" / "u.txt").write_text("héllo ✓", encoding="utf-8")
    assert read_note("u.txt") == "héllo ✓"


def test_reads_file_in_subdirectory(workdir: Path) -> None:
    sub = workdir / "notes" / "sub"
    sub.mkdir()
    (sub / "b.txt").write_text("nested", encoding="utf-8")
    assert read_note("sub/b.txt") == "nested"


def test_missing_file_is_empty(workdir: Path) -> None:
    assert read_note("nope.txt") == ""


def test_empty_name_is_empty(workdir: Path) -> None:
    assert read_note("") == ""


def test_directory_is_empty(workdir: Path) -> None:
    (workdir / "notes" / "sub").mkdir()
    assert read_note("sub") == ""
    assert read_note(".") == ""


def test_parent_traversal_is_blocked(workdir: Path) -> None:
    assert read_note("../secret.txt") == ""
    assert read_note("..") == ""
    assert read_note("sub/../../secret.txt") == ""
    assert read_note("../notes/../secret.txt") == ""


def test_deep_traversal_is_blocked(workdir: Path) -> None:
    assert read_note("../" * 20 + "etc/passwd") == ""


def test_absolute_path_is_blocked(workdir: Path) -> None:
    assert read_note(str(workdir / "secret.txt")) == ""
    assert read_note(str((workdir / "notes" / "a.txt").resolve())) == ""


def test_sibling_directory_with_same_prefix_is_blocked(workdir: Path) -> None:
    other = workdir / "notes_evil"
    other.mkdir()
    (other / "x.txt").write_text("evil", encoding="utf-8")
    assert read_note("../notes_evil/x.txt") == ""


def test_nul_byte_is_empty(workdir: Path) -> None:
    assert read_note("a.txt\x00.png") == ""
    assert read_note("\x00") == ""


def test_undecodable_file_is_empty(workdir: Path) -> None:
    (workdir / "notes" / "bin.dat").write_bytes(b"\xff\xfe\x00\xff")
    assert read_note("bin.dat") == ""


def test_symlink_escaping_notes_is_blocked(workdir: Path) -> None:
    link = workdir / "notes" / "link.txt"
    try:
        os.symlink(workdir / "secret.txt", link)
    except (OSError, NotImplementedError):
        pytest.skip("symlinks not supported")
    assert read_note("link.txt") == ""


def test_symlinked_directory_escaping_notes_is_blocked(workdir: Path) -> None:
    link = workdir / "notes" / "linkdir"
    try:
        os.symlink(workdir, link, target_is_directory=True)
    except (OSError, NotImplementedError):
        pytest.skip("symlinks not supported")
    assert read_note("linkdir/secret.txt") == ""


def test_symlink_inside_notes_is_allowed(workdir: Path) -> None:
    link = workdir / "notes" / "alias.txt"
    try:
        os.symlink(workdir / "notes" / "a.txt", link)
    except (OSError, NotImplementedError):
        pytest.skip("symlinks not supported")
    assert read_note("alias.txt") == "hello"


def test_missing_notes_directory_is_empty(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    monkeypatch.chdir(tmp_path)
    assert read_note("a.txt") == ""
